/** Offline regression for the UI refinements. No remote API or Firestore calls. */
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { tasksPage, ideasPage, assetDetailPage } from '../site/planner.js';
import { bridgePage, newBridgeState, filterStockCars, normalizeStockSearch } from '../site/marketing-bridge.js';
import { inspirationsPage, newInspirationState } from '../site/inspirations.js';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const plan=JSON.parse(fs.readFileSync(path.join(root,'data/MZJ-Publishing-Plan-2026-11-20-IMPORT.json'),'utf8'));
const state={plan,ideaKind:'all',ideaReviewFilter:'all',ideaCategoryFilter:'all',ideaSearch:'',archiveSearch:'',taskWeek:0,taskPerson:'الكل',bridge:newBridgeState(),inspirations:newInspirationState(),briefReturnView:'ideas'};
const stock=[
 {car_name:'MG 5 - NEW',statement:'ستاندرد',model_year:'2026',exterior_color:'أبيض',interior_color:'أسود'},
 {car_name:'هيونداي توسان',statement:'كومفورت',model_year:'2026',exterior_color:'رمادي',interior_color:'أسود'}
];
assert.equal(filterStockCars(stock,'MG5').length,1);
assert.equal(filterStockCars(stock,'MG 5 2026').length,1);
assert.equal(filterStockCars(stock,'توسان').length,1);
assert.equal(filterStockCars(stock,'تُوسَان').length,1);
assert.equal(normalizeStockSearch('٢٠٢٦'), '2026');
assert.equal(filterStockCars(stock,'لا توجد').length,0);
state.bridge.stock=stock;
const first=plan.assets.find(a=>a.kind!=='carousel_slide');
first.reviewStatus='معتمد';
first.marketingCategory='تعريفي - مواصفات السيارات';
state.bridge.category=first.marketingCategory;
state.bridge.selectedCodes=[first.code];
state.bridge.ideaCode=first.code;
state.bridge.stockSearch='MG5';
const name=bridgePage(state);
assert(name.includes('id="bridge-stock-search"'));
assert(name.includes('MG 5 - NEW'));
assert(!name.includes('هيونداي توسان'));
assert(name.includes('class="bridge-category-tabs"'));
assert(!name.includes('تعريفي - مواصفات السيارات ('+first.title+')'));
assert(name.includes('تعريفي - مواصفات السيارات '+first.title));
const ideas=ideasPage(state);
assert(ideas.includes('ideas-controls-center'));
assert(ideas.includes('استيراد أو استبدال JSON'));
const brief=assetDetailPage({...state,selectedAssetCode:first.code});
assert(!brief.includes('تخطيط الإنتاج'));
assert(!brief.includes('id="asset-editor"'));
assert(brief.includes('name="reviewDecision"'));
state.inspirations.formOpen=true;
const inspiration=inspirationsPage(state);
assert(inspiration.includes('بحث عن فكرة جديدة'));
assert(!inspiration.includes('إضافة مصدر إلهام جديد'));
// Test dates: hide only for unlinked test entries; do not delete or rewrite any data.
const template={...first,reviewStatus:'بانتظار المراجعة',status:'لم يبدأ',marketingTaskId:'',marketingTaskNo:'',retiredFromIdeaBank:false};
const dates=['2026-11-11','2026-11-15','2026-11-29'];
const datePlan={assets:dates.map((date,i)=>({...template,code:'TEST'+i,title:'فكرة تجربة '+i,dueDate:date})),carousels:[]};
const before=datePlan.assets.map(a=>a.dueDate);
const delivery=tasksPage({...state,plan:datePlan});
assert(delivery.includes('فكرة تجربة 0'));
assert(delivery.includes('فكرة تجربة 1'));
assert(delivery.includes('فكرة تجربة 2'));
assert(delivery.includes('بدون تاريخ'));
for(const date of dates)assert(!delivery.includes(date));
assert.deepEqual(datePlan.assets.map(a=>a.dueDate),before);
const linked=tasksPage({...state,plan:{assets:[{...datePlan.assets[0],marketingTaskId:'live-task'}],carousels:[]}});
assert(linked.includes('نوفمبر'));
const appJs=fs.readFileSync(path.join(root,'site/app.js'),'utf8');
const css=fs.readFileSync(path.join(root,'site/styles.css'),'utf8');
const theme=fs.readFileSync(path.join(root,'site/theme.css'),'utf8');
const html=fs.readFileSync(path.join(root,'site/index.html'),'utf8');
assert(!appJs.includes('data-action="open-idea-import">استيراد أفكار جديدة'));
assert(appJs.includes('workspace-kpi-donut'));
assert(appJs.includes("event.target?.id !== 'bridge-stock-search'"));
assert(html.indexOf('./theme.css')<html.indexOf('./styles.css'));
assert(theme.includes('--accent:') && theme.includes('--motion-normal:'));
assert.equal((css.match(/:root\s*\{/g)||[]).length,0,'Theme variables should have only one owner');
assert(css.includes('prefers-reduced-motion:reduce'));
console.log('PASS: dashboard donuts, centered ideas, brief, search, task names, test dates, theme and motion.');
